/**
 * guides/LEGACY-REMOVAL.md is the manifest of what 13.0.0 removes. SEMVER.md
 * lets a major release remove only what an earlier minor release marked
 * `@deprecated`, so every surface the manifest names must be marked where a
 * consumer sees it: the API report (`etc/esi.ts.api.md`, regenerated by
 * `npm run api-report`) for the root entry, the source for `./testing`.
 *
 * The cases fail when the table drifts from the expected set (a surface
 * added, dropped or renamed without updating both), when a row is malformed,
 * when a named declaration or member is missing from the report or lost its
 * tag, and when a domain client or hand-written response type exists that is
 * not covered.
 */
import { readFileSync, readdirSync } from 'fs';
import * as path from 'path';

const ROOT = path.resolve(__dirname, '../../..');
const read = (rel: string): string =>
  readFileSync(path.join(ROOT, rel), 'utf8');
const manifest = read('guides/LEGACY-REMOVAL.md');
const reportLines = read('etc/esi.ts.api.md').split('\n');

const DOMAIN_CLIENTS = [
  'AccessListsClient',
  'AllianceClient',
  'AssetsClient',
  'CalendarClient',
  'CharacterClient',
  'CharacterSkillsClient',
  'ClonesClient',
  'ContactsClient',
  'ContractsClient',
  'CorporationProjectsClient',
  'CorporationsClient',
  'CosmeticsClient',
  'DogmaClient',
  'FactionClient',
  'FittingsClient',
  'FleetClient',
  'FreelanceJobsClient',
  'IncursionsClient',
  'IndustryClient',
  'InsuranceClient',
  'KillmailsClient',
  'LocationClient',
  'LoyaltyClient',
  'MailClient',
  'MarketClient',
  'MercenaryClient',
  'MetaClient',
  'MilitaryCampaignsClient',
  'ParagonHubClient',
  'PiClient',
  'RouteClient',
  'SearchClient',
  'SkyhooksClient',
  'SovereigntyClient',
  'StatusClient',
  'UiClient',
  'UniverseClient',
  'WalletClient',
  'WarsClient',
];

/** Every surface the Surfaces table must list, and nothing else. */
const EXPECTED = [
  'EsiClient',
  'getDefaultClient',
  'EsiClientBuilder',
  'CustomEsiClient',
  'EsiApiFactory',
  'EsiApiFactory.createClient',
  'EsiApiFactory.createAllianceClient',
  'EsiApiFactory.createCharacterClient',
  'EsiApiFactory.createCorporationClient',
  'EsiApiFactory.createMarketClient',
  'EsiApiFactory.createUniverseClient',
  'EsiApiFactory.createFleetClient',
  'EsiApiFactory.createAssetsClient',
  'EsiApiFactory.createWalletClient',
  'EsiApiFactory.createMailClient',
  'ApiClientType',
  'ApiClientBuilder',
  'BaseEsiClient',
  'RouteOptions',
  'EsiTokenManager.createClient',
  'ManagedClientConfig',
  'ApiClient',
  'configureApiClient',
  'ConfigureApiClientResult',
  'EsiClientConfig',
  'buildEndpointPath',
  'DeprecationInfo',
  'CreateClientOptions',
  'WithMetadata',
  'WithSafeMode',
  'InferEndpointResult',
  'UnwrapArray',
  'CursorOptions',
  'CursorResult',
  'CursorTokens',
  'fetchAllCursorPages',
  'fetchAllPages',
  'fetchPages',
  'PageResult',
  'batchFetch',
  'batchPost',
  'BatchOptions',
  'BatchResult',
  'EsiDiagnostics',
  'CacheStats',
  'CircuitBreakerStats',
  ...DOMAIN_CLIENTS,
];

const KINDS = new Set(['class', 'function', 'method', 'type', 'interface']);

interface Surface {
  readonly name: string;
  readonly kind: string;
  readonly since: string;
  readonly replacement: string;
  readonly removedIn: string;
}

/**
 * The first table under `## Surfaces`: its data rows, and a problem for each
 * row that does not read `| `Name` | kind | x.y.0 | replacement | 13.0.0 |`.
 */
function parseSurfaces(markdown: string): {
  rows: Surface[];
  problems: string[];
} {
  const lines = markdown.split('\n');
  const heading = lines.indexOf('## Surfaces');
  const rows: Surface[] = [];
  const problems: string[] = [];
  if (heading < 0) return { rows, problems: ['no "## Surfaces" heading'] };
  let i = heading + 1;
  while (i < lines.length && !lines[i]!.startsWith('|')) i++;
  // Header and separator rows first.
  const header = lines[i] ?? '';
  if (!/^\|\s*Surface\s*\|/.test(header)) problems.push('no table header');
  i += 2;
  for (; i < lines.length && lines[i]!.startsWith('|'); i++) {
    const line = lines[i]!;
    const cells = line
      .split('|')
      .slice(1, -1)
      .map((c) => c.trim());
    const name = /^`([A-Za-z]\w*(?:\.\w+)?)`$/.exec(cells[0] ?? '');
    const row: Surface = {
      name: name?.[1] ?? '',
      kind: cells[1] ?? '',
      since: cells[2] ?? '',
      replacement: cells[3] ?? '',
      removedIn: cells[4] ?? '',
    };
    const wrong: string[] = [];
    if (cells.length !== 5) wrong.push(`${cells.length} columns`);
    if (!name) wrong.push('surface is not one backticked name');
    if (!KINDS.has(row.kind)) wrong.push(`kind "${row.kind}"`);
    if (!/^\d+\.\d+\.0$/.test(row.since)) wrong.push(`since "${row.since}"`);
    if (row.replacement.length < 4) wrong.push('no replacement');
    if (row.removedIn !== '13.0.0') wrong.push(`removed in "${row.removedIn}"`);
    if (wrong.length > 0) problems.push(`${line}: ${wrong.join(', ')}`);
    rows.push(row);
  }
  return { rows, problems };
}

const DECLARATION =
  /^(export )?(?:declare )?(?:abstract )?(?:class|interface|type|function|const|enum) (\w+)\b/;

/**
 * The indexes of `name`'s top-level declarations in the report (a value and a
 * type may share one). A name that clashes with a global, such as
 * `Notification`, is declared as `Notification_2` and exported with
 * `export { Notification_2 as Notification }`.
 */
function declarationIndexes(name: string): number[] {
  const alias = reportLines
    .map((line) => /^export \{ (\w+) as (\w+) \}/.exec(line))
    .find((m) => m?.[2] === name)?.[1];
  const found: number[] = [];
  reportLines.forEach((line, i) => {
    const m = DECLARATION.exec(line);
    if (!m) return;
    if (m[1] && m[2] === name) found.push(i);
    if (!m[1] && alias !== undefined && m[2] === alias) found.push(i);
  });
  return found;
}

/** The comment lines directly above line `index`. */
function commentAbove(index: number): string[] {
  const comments: string[] = [];
  for (let i = index - 1; i >= 0; i--) {
    const line = reportLines[i]!.trim();
    if (!line.startsWith('//')) break;
    comments.push(line);
  }
  return comments;
}

/** The index of member `member` inside the class declared at `classIndex`, or -1. */
function memberIndex(classIndex: number, member: string): number {
  const pattern = new RegExp(
    `^\\s+(?:static |protected |abstract )*${member}[(<]`,
  );
  for (let i = classIndex + 1; i < reportLines.length; i++) {
    const line = reportLines[i]!;
    if (line === '}') return -1;
    if (pattern.test(line)) return i;
  }
  return -1;
}

/** Whether every declaration of `name` (or `Owner.member`) in the report carries the tag. */
function isDeprecated(name: string): 'missing' | 'untagged' | 'tagged' {
  const [owner, member] = name.split('.') as [string, string | undefined];
  const owners = declarationIndexes(owner);
  if (owners.length === 0) return 'missing';
  const indexes = member
    ? owners.map((o) => memberIndex(o, member)).filter((i) => i >= 0)
    : owners;
  if (indexes.length === 0) return 'missing';
  return indexes.every((i) =>
    commentAbove(i).some((c) => c.includes('@deprecated')),
  )
    ? 'tagged'
    : 'untagged';
}

/** Every type the hand-written response modules export (branded IDs excluded). */
function responseTypeNames(): string[] {
  const dir = path.join(ROOT, 'src/types');
  const names: string[] = [];
  for (const file of readdirSync(dir)) {
    if (!file.endsWith('.ts')) continue;
    if (file === 'branded.ts' || file === 'api-responses.ts') continue;
    const text = readFileSync(path.join(dir, file), 'utf8');
    for (const m of text.matchAll(/^export (?:type|interface) (\w+)/gm)) {
      names.push(m[1]!);
    }
  }
  return names;
}

const { rows, problems } = parseSurfaces(manifest);

describe('guides/LEGACY-REMOVAL.md and the API report agree', () => {
  it('lists exactly the expected surfaces, each once', () => {
    const names = rows.map((r) => r.name);
    expect([...names].sort()).toEqual([...EXPECTED].sort());
  });

  it('has no malformed row in the surfaces table', () => {
    expect(problems).toEqual([]);
  });

  it('marks every surface in the table @deprecated in etc/esi.ts.api.md', () => {
    const wrong = rows
      .map((r) => ({ name: r.name, state: isDeprecated(r.name) }))
      .filter((r) => r.state !== 'tagged');
    expect(wrong).toEqual([]);
  });

  it('lists every domain client the report exports', () => {
    const clients = reportLines
      .map((line) => /^export class (\w+) extends BaseEsiClient\b/.exec(line))
      .filter((m): m is RegExpExecArray => m !== null)
      .map((m) => m[1]!);
    expect([...clients].sort()).toEqual([...DOMAIN_CLIENTS].sort());
  });

  it('marks every hand-written response type @deprecated in the report', () => {
    const names = responseTypeNames();
    expect(names.length).toBeGreaterThan(150);
    const wrong = names
      .map((name) => ({ name, state: isDeprecated(name) }))
      .filter((r) => r.state !== 'tagged');
    expect(wrong).toEqual([]);
  });

  it('marks TestDataFactory @deprecated where ./testing declares it', () => {
    const source = read('src/testing/TestDataFactory.ts');
    expect(source).toMatch(
      /@deprecated Since 12\.1\.0; removed in 13\.0\.0[\s\S]*?\*\/\nexport class TestDataFactory\b/,
    );
  });

  it('records the ./schemas entry deprecation in its module documentation', () => {
    expect(read('src/schemas/index.ts')).toMatch(
      /Deprecated since 12\.1\.0 as a whole and removed in 13\.0\.0/,
    );
  });

  it('reports a name that is not in the API report as missing', () => {
    // Guards the lookup itself: a typo in the table must not read as tagged.
    expect(isDeprecated('NoSuchExport')).toBe('missing');
    expect(isDeprecated('EsiClient.noSuchMember')).toBe('missing');
  });

  it('reports a declaration without the tag as untagged', () => {
    // createEsi's runtime and the error classes stay; the check must tell.
    expect(isDeprecated('EsiError')).toBe('untagged');
    expect(isDeprecated('EsiTokenManager.identity')).toBe('untagged');
  });

  it('flags a malformed row', () => {
    const bad = parseSurfaces(
      [
        '## Surfaces',
        '',
        '| Surface | Kind | Deprecated since | Replacement | Removed in |',
        '| --- | --- | --- | --- | --- |',
        '| `Foo` | class | 12.1.0 | | 13.0.0 |',
        '| `Bar` | gizmo | soon | `createEsi()` | 14.0.0 |',
        '| Baz | class | 12.1.0 | `createEsi()` |',
      ].join('\n'),
    );
    expect(bad.problems).toHaveLength(3);
  });
});
